mapper.update:
UPDATE
    l_admin


        group_id = #{adminGroupId}


        name = #{name}


        password = #{password}


        salt = #{salt}


        description = #{description}


        status = #{status}

    edit_time = #{editTime}

WHERE
    id = #{id}

mapper.select:
SELECT a.*, ag.name group_name, (SELECT login_time FROM l_admin_login_record WHERE admin_id = a.id ORDER BY login_time DESC LIMIT 1) last_login_time FROM l_admin a LEFT JOIN l_admin_group ag ON a.group_id = ag.id
AND a.name = #{admin.name}
AND a.status = #{admin.status}
ORDER BY a.id DESC LIMIT #{startNum}, #{size}

SELECT
    COUNT(id)
FROM
    l_admin


        AND group_id = #{groupId}


        AND name = #{name}


        AND status = #{status}
